{"name": "matrix_power_mod", "arguments": {"solve": "def solve(inputs: dict) -> float:
    from math import floor

    def matrix_multiply(X, Y):
        return [
            [floor((X[0][0] * Y[0][0] + X[0][1] * Y[1][0]) % inputs['MOD']), floor((X[0][0] * Y[0][1] + X[0][1] * Y[1][1]) % inputs['MOD'])],
            [floor((X[1][0] * Y[0][0] + X[1][1] * Y[1][0]) % inputs['MOD']), floor((X[1][0] * Y[0][1] + X[1][1] * Y[1][1]) % inputs['MOD'])]
        ]

    def fast_matrix_power(matrix, power):
        result = [[1, 0], [0, 1]]
        base = matrix
        while power > 0:
            if power % 2 == 1:
                result = matrix_multiply(result, base)
            base = matrix_multiply(base, base)
            power //= 2
        return result

    M = [[inputs['A']], [inputs['C']]]
    X = fast_matrix_power([[inputs['A'], inputs['B']], [inputs['C'], inputs['D']]], floor(inputs['K']))

    result_m = matrix_multiply(X, M)
    return (result_m[0][0] + result_m[1][0]) % inputs['MOD']"}}
